func loadBounded(graphPath string, max int64) (*Map, error) {
	file, err := os.Open(graphPath)
	if err != nil {
		return nil, fmt.Errorf("repomap: reading %s: %w", graphPath, err)
	}
	defer file.Close()

	raw, err := readBounded(file, max)
	if err != nil {
		return nil, fmt.Errorf("repomap: reading %s: %w", graphPath, err)
	}
	g, err := decodeGraph(raw)
	if err != nil {
		// A layout this build cannot read is a different report from a file it
		// cannot parse, and keeping them apart is the difference between "the
		// producer moved ahead of this harness" and "the artifact is damaged".
		// They send an operator to different places.
		if errors.Is(err, ErrUnknownCompactLayout) {
			return nil, fmt.Errorf("repomap: %s: %w", graphPath, err)
		}
		return nil, fmt.Errorf("repomap: %s is not a code graph: %w", graphPath, err)
	}
	if len(g.Nodes) == 0 {
		return nil, fmt.Errorf("repomap: %s holds no nodes; the index has not been built", graphPath)
	}
	return build(g), nil
}

def describe_corpus(repo: Path) -> Dict[str, object]:
    """Count tracked files and code files so throughput has a denominator.

    Falls back to a filesystem walk outside a git repository — the engine
    indexes trees, not just checkouts, and a benchmark that only runs on git
    repos cannot measure the case it is most often asked about.
    """
    try:
        out = subprocess.run(
            ["git", "ls-files"], cwd=str(repo), capture_output=True, text=True, timeout=120
        )
        files = [f for f in out.stdout.splitlines() if f] if out.returncode == 0 else []
    except (OSError, subprocess.SubprocessError):
        files = []
    if not files:
        files = [
            str(p.relative_to(repo))
            for p in repo.rglob("*")
            if p.is_file() and ".git" not in p.parts
        ]
    code = [f for f in files if Path(f).suffix.lower() in _CODE_SUFFIXES]
    total_bytes = 0
    for rel in code:
        try:
            total_bytes += (repo / rel).stat().st_size
        except OSError:
            pass
    return {
        "tracked_files": len(files),
        "code_files": len(code),
        "code_bytes": total_bytes,
    }

